<script setup lang="ts">
import '@vue-flow/core/dist/style.css'
import '@vue-flow/core/dist/theme-default.css'
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { VueFlow, MarkerType, getRectOfNodes, getTransformForBounds, type Edge, type Node, useVueFlow } from '@vue-flow/core'
import { Background } from '@vue-flow/background'
import { useDialog, useMessage } from 'naive-ui'
import { toPng } from 'html-to-image'
import SystemNodeCard from '../components/SystemNodeCard.vue'
import ShareDialog from '../components/ShareDialog.vue'
import { api } from '../services/api'
import type { Rule, Setting, SystemNode, TradingSystemDetail, TradingSystemSummary } from '../types'

interface MindmapCategory extends Setting { mindmap_count:number; template_count:number }
interface MindmapVersion { id:number; action:string; label?:string|null; created_at:string; snapshot_size:number }
const ALL='__all__'
const message=useMessage(),dialog=useDialog();const {fitView,zoomIn,zoomOut,getNodes}=useVueFlow();const loading=ref(false),systems=ref<TradingSystemSummary[]>([]),activeId=ref<number|null>(null),detail=ref<TradingSystemDetail|null>(null),flowNodes=ref<Node[]>([]),flowEdges=ref<Edge[]>([]),showSystemForm=ref(false),editingSystemId=ref<number|null>(null),showNodeForm=ref(false),editingNodeId=ref<number|null>(null),parentNodeId=ref<number|null>(null),rules=ref<Rule[]>([]),nodeTypeSettings=ref<Setting[]>([]),mindmapCategories=ref<MindmapCategory[]>([]),categoryFilter=ref(ALL),flowCanvas=ref<HTMLElement|null>(null),pageRoot=ref<HTMLElement|null>(null),isFullscreen=ref(false),nodeSaving=ref(false),showCategories=ref(false),categorySaving=ref(false),editingCategoryId=ref<number|null>(null),mindmapTotal=ref(0),searchQuery=ref(''),statusFilter=ref(ALL),showVersions=ref(false),versions=ref<MindmapVersion[]>([]),showTemplates=ref(false),templates=ref<TradingSystemSummary[]>([]),dragCategoryId=ref<number|null>(null),showShare=ref(false)
let resizeObserver:ResizeObserver|null=null,fitTimer:number|undefined
const systemForm=reactive({name:'',category:'交易系统',description:'',resource_url:'',markets:'',timeframes:'',status:'draft',color:'#3ec9c5',template:true})
const nodeForm=reactive<any>({title:'',content:'',node_type:'condition',parent_id:null,rule_id:null,sort_order:0,is_collapsed:false})
const categoryForm=reactive({name:'',color:'#3ec9c5'})
const statusLabel:Record<string,string>={draft:'草稿',active:'执行中',archived:'已归档'}
const activeSystem=computed(()=>detail.value?.system)
const mindmapCategoryOptions=computed(()=>mindmapCategories.value.map(item=>({label:item.label,value:item.value,disabled:!Boolean(item.is_active)})))
const visibleMindmapCategories=computed(()=>mindmapCategories.value.filter(item=>Boolean(item.is_active)||Number(item.mindmap_count)>0))
const moreOptions=[{label:'复制脑图',key:'duplicate'},{label:'保存为模板',key:'template'},{type:'divider',key:'d1'},{label:'导出 PNG',key:'png'},{label:'导出 Markdown',key:'markdown'},{label:'导出 JSON',key:'json'}]
function handleMore(key:string){if(key==='duplicate')void duplicateCurrent();else if(key==='template')void saveAsTemplate();else if(key==='png')void exportPng();else if(key==='markdown')exportMarkdown();else if(key==='json')exportJson()}

async function loadSystems(preferred=activeId.value){const params=new URLSearchParams();if(categoryFilter.value!==ALL)params.set('category',categoryFilter.value);if(searchQuery.value.trim())params.set('q',searchQuery.value.trim());if(statusFilter.value!==ALL)params.set('status',statusFilter.value);systems.value=await api.get(`/systems${params.size?`?${params}`:''}`);if(!systems.value.length){activeId.value=null;detail.value=null;return}const target=systems.value.some(v=>v.id===preferred)?preferred:systems.value[0].id;await select(Number(target))}
async function loadNodeTypes(){nodeTypeSettings.value=await api.get('/settings?category=system_node_type')}
async function loadMindmapCategories(){const data=await api.get<{categories:MindmapCategory[];total:number}>('/systems/categories');mindmapCategories.value=data.categories||[];mindmapTotal.value=data.total||0}
async function refreshMindmaps(preferred=activeId.value){await Promise.all([loadSystems(preferred),loadMindmapCategories()])}
function selectCategory(value:string){categoryFilter.value=value;void loadSystems()}
function openCategoryManager(){editingCategoryId.value=null;Object.assign(categoryForm,{name:'',color:'#3ec9c5'});showCategories.value=true}
function editCategory(item:MindmapCategory){editingCategoryId.value=item.id;Object.assign(categoryForm,{name:item.label,color:item.color||'#3ec9c5'})}
function cancelCategoryEdit(){editingCategoryId.value=null;Object.assign(categoryForm,{name:'',color:'#3ec9c5'})}
function categoryUseCount(item:MindmapCategory){return Number(item.mindmap_count||0)+Number(item.template_count||0)}
async function saveCategory(){const name=categoryForm.name.trim();if(!name)return message.error('请输入分类名称');if(name.length>60)return message.error('分类名称最多 60 个字符');categorySaving.value=true;try{const current=editingCategoryId.value?mindmapCategories.value.find(item=>item.id===editingCategoryId.value):undefined;const payload={category:'mindmap_category',label:name,value:name,color:categoryForm.color,sort_order:current?.sort_order??mindmapCategories.value.length,is_active:current?Boolean(current.is_active):true};if(current){await api.put(`/settings/${current.id}`,payload);if(categoryFilter.value===current.value)categoryFilter.value=name;if(systemForm.category===current.value)systemForm.category=name;message.success('分类已更新，已有脑图已同步')}else{await api.post('/settings',payload);systemForm.category=name;message.success('分类已创建')}cancelCategoryEdit();await refreshMindmaps()}catch(error){message.error(error instanceof Error?error.message:'分类保存失败')}finally{categorySaving.value=false}}
async function toggleCategory(item:MindmapCategory,active:boolean){try{await api.put(`/settings/${item.id}`,{is_active:active});await loadMindmapCategories();message.success(active?'分类已启用':'分类已停用')}catch(error){message.error(error instanceof Error?error.message:'分类状态更新失败')}}
function removeCategory(item:MindmapCategory){const used=categoryUseCount(item);dialog.warning({title:'删除脑图分类',content:used?`“${item.label}”中有 ${item.mindmap_count} 张脑图和 ${item.template_count||0} 个模板。脑图不允许未分类，请先移动或删除这些内容。`:`确定删除“${item.label}”分类吗？`,positiveText:'删除分类',negativeText:'取消',positiveButtonProps:{disabled:used>0},async onPositiveClick(){try{await api.del(`/settings/${item.id}`);if(categoryFilter.value===item.value)categoryFilter.value=ALL;if(editingCategoryId.value===item.id)cancelCategoryEdit();message.success('分类已删除');await refreshMindmaps()}catch(error){message.error(error instanceof Error?error.message:'分类删除失败')}}})}
async function dropCategory(targetId:number){const sourceId=dragCategoryId.value;dragCategoryId.value=null;if(!sourceId||sourceId===targetId)return;const ordered=[...mindmapCategories.value],from=ordered.findIndex(v=>v.id===sourceId),to=ordered.findIndex(v=>v.id===targetId);if(from<0||to<0)return;const [moved]=ordered.splice(from,1);ordered.splice(to,0,moved);mindmapCategories.value=ordered;try{await Promise.all(ordered.map((item,index)=>api.put(`/settings/${item.id}`,{sort_order:index})));await loadMindmapCategories();message.success('分类顺序已保存')}catch(error){message.error(error instanceof Error?error.message:'分类排序失败');await loadMindmapCategories()}}
async function select(id:number){activeId.value=id;loading.value=true;try{detail.value=await api.get(`/systems/${id}`);buildFlow();await nextTick();observeCanvas();window.setTimeout(()=>fitView({padding:.18,duration:300}),40)}finally{loading.value=false}}
function estimatedNodeHeight(node:SystemNode){const titleLines=Math.max(1,Math.ceil(String(node.title||'').length/18));const contentLines=node.content?Math.max(1,Math.ceil(String(node.content).length/32)):0;return 72+titleLines*17+contentLines*14+(node.rule_id?22:0)}
function visibleLayout(nodes:SystemNode[]){const map=new Map(nodes.map(n=>[n.id,{...n,children:[] as SystemNode[]}]));let root:any=null;for(const node of map.values()){const parent=map.get(Number(node.parent_id));if(parent)parent.children.push(node);else if(!root||node.node_type==='root')root=node}for(const node of map.values())node.children.sort((a:any,b:any)=>a.sort_order-b.sort_order||a.id-b.id);let cursor=0;const positions=new Map<number,{x:number;y:number}>();const edges:Edge[]=[];function visit(node:any,depth:number):number{const children=node.is_collapsed?[]:node.children;const height=estimatedNodeHeight(node);let center;if(!children.length){center=cursor+height/2;cursor+=height+34}else{const centers=children.map((c:any)=>visit(c,depth+1));center=(centers[0]+centers[centers.length-1])/2;for(const c of children)edges.push({id:`e-${node.id}-${c.id}`,source:String(node.id),target:String(c.id),type:'bezier',markerEnd:MarkerType.ArrowClosed,style:{stroke:'#2b6671',strokeWidth:1.6}})}positions.set(node.id,{x:depth*350,y:Math.max(0,center-height/2)});return center}if(root)visit(root,0);return{map,positions,edges}}
function buildFlow(){
  if(!detail.value)return
  const {map,positions,edges}=visibleLayout(detail.value.nodes)
  const nextNodes:any[]=[]
  for(const [id,position] of positions.entries()){
    const node=map.get(id)!
    const typeSetting=nodeTypeSettings.value.find(item=>item.value===node.node_type)
    nextNodes.push({id:String(id),type:'system',position,data:{node,childCount:node.children.length,typeLabel:typeSetting?.label,typeColor:typeSetting?.color,onAdd:openNewNode,onEdit:openEditNode,onDelete:removeNode,onToggle:toggleNode},draggable:false})
  }
  flowNodes.value=nextNodes
  flowEdges.value=edges
}
function openSystem(system?:TradingSystemSummary){editingSystemId.value=system?.id??null;Object.assign(systemForm,system?{name:system.name,category:system.category||'',description:system.description||'',resource_url:system.resource_url||'',markets:system.markets||'',timeframes:system.timeframes||'',status:system.status,color:system.color,template:true}:{name:'',category:mindmapCategories.value.find(v=>Boolean(v.is_active))?.value||'交易系统',description:'',resource_url:'',markets:'',timeframes:'',status:'draft',color:'#3ec9c5',template:true});showSystemForm.value=true}
async function saveSystem(){if(!systemForm.name.trim())return message.error('请填写脑图名称');if(!systemForm.category)return message.error('请选择脑图分类');if(editingSystemId.value){const id=editingSystemId.value;await api.put(`/systems/${id}`,systemForm);message.success('脑图已更新');showSystemForm.value=false;await refreshMindmaps(id)}else{const result=await api.post<{id:number}>('/systems',systemForm);message.success('脑图已创建');showSystemForm.value=false;categoryFilter.value=systemForm.category;await refreshMindmaps(result.id)}}
function editCurrent(){if(activeSystem.value)openSystem(activeSystem.value)}
function removeSystem(){if(!activeSystem.value)return;dialog.warning({title:'删除脑图',content:`确定删除“${activeSystem.value.name}”及全部脑图节点吗？历史交易会保留。`,positiveText:'删除',negativeText:'取消',async onPositiveClick(){try{await api.del(`/systems/${activeSystem.value!.id}`);message.success('脑图已删除');activeId.value=null;await refreshMindmaps()}catch(error){message.error(error instanceof Error?error.message:'脑图删除失败')}}})}
async function duplicateCurrent(){if(!activeSystem.value)return;try{const result=await api.post<{id:number}>(`/systems/${activeSystem.value.id}/duplicate`);message.success('副本已创建');await refreshMindmaps(result.id)}catch(error){message.error(error instanceof Error?error.message:'复制失败')}}
async function saveAsTemplate(){if(!activeSystem.value)return;try{await api.post(`/systems/${activeSystem.value.id}/template`);message.success('已保存为脑图模板')}catch(error){message.error(error instanceof Error?error.message:'保存模板失败')}}
async function openTemplates(){templates.value=await api.get('/systems/templates');showTemplates.value=true}
async function useTemplate(item:TradingSystemSummary){try{const result=await api.post<{id:number}>(`/systems/templates/${item.id}/create`);showTemplates.value=false;message.success('已从模板创建脑图');categoryFilter.value=ALL;await refreshMindmaps(result.id)}catch(error){message.error(error instanceof Error?error.message:'创建失败')}}
async function deleteTemplate(item:TradingSystemSummary){try{await api.del(`/systems/${item.id}`);templates.value=templates.value.filter(v=>v.id!==item.id);message.success('模板已删除')}catch(error){message.error(error instanceof Error?error.message:'删除模板失败')}}
async function openVersionHistory(){if(!activeSystem.value)return;versions.value=await api.get(`/systems/${activeSystem.value.id}/versions`);showVersions.value=true}
async function saveVersion(){if(!activeSystem.value)return;try{await api.post(`/systems/${activeSystem.value.id}/versions`,{label:'手动保存'});message.success('当前整图版本已保存');await openVersionHistory()}catch(error){message.error(error instanceof Error?error.message:'保存版本失败')}}
function restoreVersion(item:MindmapVersion){if(!activeSystem.value)return;dialog.warning({title:'回撤整张脑图',content:`回撤到 ${new Date(item.created_at).toLocaleString()} 的“${item.label||item.action}”版本？当前内容会先自动备份。`,positiveText:'确认回撤',negativeText:'取消',async onPositiveClick(){try{await api.post(`/systems/${activeSystem.value!.id}/versions/${item.id}/restore`);showVersions.value=false;message.success('整张脑图已回撤');await refreshMindmaps(activeSystem.value!.id)}catch(error){message.error(error instanceof Error?error.message:'回撤失败')}}})}
function removeVersion(item:MindmapVersion){if(!activeSystem.value)return;dialog.warning({title:'删除脑图版本',content:`确定删除“${item.label||item.action}”版本吗？交易中保存的完整脑图快照不会被删除，但该版本无法再用于整图回撤。`,positiveText:'删除版本',negativeText:'取消',async onPositiveClick(){try{await api.del(`/systems/${activeSystem.value!.id}/versions/${item.id}`);versions.value=versions.value.filter(version=>version.id!==item.id);message.success('脑图版本已删除')}catch(error){message.error(error instanceof Error?error.message:'版本删除失败')}}})}
function downloadFile(name:string,content:string,type:string){const url=URL.createObjectURL(new Blob([content],{type}));const anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();URL.revokeObjectURL(url)}
function safeFileName(name:string){return name.replace(/[\\/:*?"<>|]/g,'_')}
function exportJson(){if(!detail.value)return;downloadFile(`${safeFileName(detail.value.system.name)}.json`,JSON.stringify(detail.value,null,2),'application/json')}
function exportMarkdown(){if(!detail.value)return;const children=new Map<number,SystemNode[]>();for(const node of detail.value.nodes){if(node.parent_id!==null)children.set(node.parent_id,[...(children.get(node.parent_id)||[]),node])}for(const list of children.values())list.sort((a,b)=>a.sort_order-b.sort_order||a.id-b.id);const root=detail.value.nodes.find(v=>v.parent_id===null);const lines=[`# ${detail.value.system.name}`,'',detail.value.system.description||'',''];function walk(parent:number,depth:number){for(const node of children.get(parent)||[]){lines.push(`${'  '.repeat(Math.max(0,depth-2))}- **${node.title}**${node.content?`：${node.content}`:''}`);walk(node.id,depth+1)}}if(root)walk(root.id,2);downloadFile(`${safeFileName(detail.value.system.name)}.md`,lines.join('\n'),'text/markdown;charset=utf-8')}
async function exportPng(){if(!flowCanvas.value||!activeSystem.value||!detail.value)return;const collapsed=detail.value.nodes.map(node=>Boolean(node.is_collapsed));try{detail.value.nodes.forEach(node=>node.is_collapsed=false);buildFlow();await nextTick();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const graphNodes=getNodes.value;if(!graphNodes.length)throw new Error('脑图还没有节点');const bounds=getRectOfNodes(graphNodes);const padding=80,width=Math.max(900,Math.ceil(bounds.width+padding*2)),height=Math.max(600,Math.ceil(bounds.height+padding*2));const {x,y,zoom}=getTransformForBounds(bounds,width,height,.1,1,.92);const viewport=flowCanvas.value.querySelector<HTMLElement>('.vue-flow__viewport');if(!viewport)throw new Error('无法读取脑图画布');const data=await toPng(viewport,{backgroundColor:'#0a0f17',pixelRatio:2,width,height,style:{width:`${width}px`,height:`${height}px`,transform:`translate(${x}px, ${y}px) scale(${zoom})`,transformOrigin:'top left'},filter:node=>!node.classList?.contains('flow-controls')&&!node.classList?.contains('flow-touch-hint')});const anchor=document.createElement('a');anchor.href=data;anchor.download=`${safeFileName(activeSystem.value.name)}.png`;anchor.click()}catch(error){message.error(error instanceof Error?error.message:'PNG 导出失败')}finally{detail.value.nodes.forEach((node,index)=>node.is_collapsed=collapsed[index]);buildFlow();await nextTick();fitView({padding:.18,duration:180})}}
async function ensureRules(){if(!rules.value.length)rules.value=await api.get('/rules?active=true')}
async function openNewNode(parentId:number){await ensureRules();editingNodeId.value=null;parentNodeId.value=parentId;Object.assign(nodeForm,{title:'',content:'',node_type:defaultNodeType.value,parent_id:parentId,rule_id:null,sort_order:0,is_collapsed:false});showNodeForm.value=true}
async function openEditNode(node:SystemNode){await ensureRules();editingNodeId.value=node.id;parentNodeId.value=node.parent_id;Object.assign(nodeForm,{title:node.title,content:node.content||'',node_type:node.node_type,parent_id:node.parent_id,rule_id:node.rule_id||null,sort_order:node.sort_order,is_collapsed:Boolean(node.is_collapsed)});showNodeForm.value=true}
function editFlowNode(event:any){const node=event?.node?.data?.node as SystemNode|undefined;if(node)openEditNode(node)}
function editNodeAtPoint(event:MouseEvent){
  if((event.target as HTMLElement).closest('button,.vue-flow__controls'))return
  for(const element of document.querySelectorAll<HTMLElement>('.vue-flow__node')){
    const rect=element.getBoundingClientRect()
    if(event.clientX>=rect.left&&event.clientX<=rect.right&&event.clientY>=rect.top&&event.clientY<=rect.bottom){
      const node=detail.value?.nodes.find(item=>item.id===Number(element.dataset.id))
      if(node)openEditNode(node)
      return
    }
  }
}
function updateLocalNodeCount(){if(!detail.value)return;const count=detail.value.nodes.length;detail.value.system.node_count=count;const summary=systems.value.find(system=>system.id===detail.value!.system.id);if(summary)summary.node_count=count}
function rebuildAfterMutation(fit=false){buildFlow();void nextTick().then(()=>{if(fit)scheduleFit()})}
async function saveNode(){if(!activeId.value||!detail.value||!nodeForm.title.trim())return message.error('请填写节点名称');if(nodeSaving.value)return;nodeSaving.value=true;const editingId=editingNodeId.value;const payload={...nodeForm};try{if(editingId){await api.put(`/systems/${activeId.value}/nodes/${editingId}`,payload);const index=detail.value.nodes.findIndex(node=>node.id===editingId);if(index>=0){const rule=rules.value.find(item=>item.id===payload.rule_id);detail.value.nodes[index]={...detail.value.nodes[index],...payload,is_collapsed:Boolean(payload.is_collapsed),rule_title:rule?.title||null,rule_category:rule?.category||null}}}else{const result=await api.post<{id:number}>(`/systems/${activeId.value}/nodes`,payload);const rule=rules.value.find(item=>item.id===payload.rule_id);detail.value.nodes.push({id:result.id,system_id:activeId.value,parent_id:payload.parent_id,rule_id:payload.rule_id,title:payload.title,content:payload.content,node_type:payload.node_type,sort_order:payload.sort_order,is_collapsed:Boolean(payload.is_collapsed),rule_title:rule?.title||null,rule_category:rule?.category||null})}updateLocalNodeCount();rebuildAfterMutation(!editingId);message.success(editingId?'节点已更新':'节点已添加');showNodeForm.value=false}catch(error){message.error(error instanceof Error?error.message:'节点保存失败')}finally{nodeSaving.value=false}}
async function toggleNode(node:SystemNode){if(!activeId.value)return;const collapsed=!Boolean(node.is_collapsed);await api.put(`/systems/${activeId.value}/nodes/${node.id}`,{is_collapsed:collapsed});node.is_collapsed=collapsed;rebuildAfterMutation()}
function descendantIds(id:number){if(!detail.value)return new Set<number>();const children=new Map<number,number[]>();for(const item of detail.value.nodes){const key=Number(item.parent_id);children.set(key,[...(children.get(key)||[]),item.id])}const ids=new Set<number>([id]),stack=[id];while(stack.length){for(const child of children.get(stack.pop()!)||[]){ids.add(child);stack.push(child)}}return ids}
function removeNode(node:SystemNode){const descendants=countDescendants(node.id);dialog.warning({title:'删除节点',content:`确定删除“${node.title}”吗？${descendants?`它的 ${descendants} 个子节点也会删除。`:''}`,positiveText:'删除',negativeText:'取消',async onPositiveClick(){try{await api.del(`/systems/${activeId.value}/nodes/${node.id}`);if(detail.value){const removed=descendantIds(node.id);detail.value.nodes=detail.value.nodes.filter(item=>!removed.has(item.id));updateLocalNodeCount();rebuildAfterMutation(true)}message.success('节点已删除')}catch(error){message.error(error instanceof Error?error.message:'节点删除失败')}}})}
function countDescendants(id:number){if(!detail.value)return 0;const children=new Map<number,number[]>();for(const n of detail.value.nodes){const key=Number(n.parent_id);children.set(key,[...(children.get(key)||[]),n.id])}let count=0,stack=[id];while(stack.length){for(const child of children.get(stack.pop()!)||[]){count++;stack.push(child)}}return count}
const parentOptions=computed(()=>detail.value?.nodes.filter(n=>n.id!==editingNodeId.value).map(n=>({label:`${'— '.repeat(Math.min(4,nodeDepth(n.id)))}${n.title}`,value:n.id}))||[])
function nodeDepth(id:number){if(!detail.value)return 0;const map=new Map(detail.value.nodes.map(n=>[n.id,n]));let d=0,n=map.get(id),guard=0;while(n?.parent_id&&guard++<20){d++;n=map.get(n.parent_id)}return d}
const ruleOptions=computed(()=>rules.value.map(r=>({label:`[${r.category}] ${r.title}`,value:r.id})))
const nodeTypes=computed(()=>{
  const options=nodeTypeSettings.value.map(item=>({value:item.value,label:item.label,disabled:!Boolean(item.is_active)}))
  if(nodeForm.node_type==='root')options.unshift({value:'root',label:'系统根节点',disabled:true})
  else if(nodeForm.node_type&&!options.some(item=>item.value===nodeForm.node_type))options.unshift({value:nodeForm.node_type,label:`${nodeForm.node_type}（已删除）`,disabled:true})
  return options
})
const defaultNodeType=computed(()=>nodeTypeSettings.value.find(item=>Boolean(item.is_active)&&item.value==='condition')?.value||nodeTypeSettings.value.find(item=>Boolean(item.is_active))?.value||'condition')
function scheduleFit(){clearTimeout(fitTimer);fitTimer=window.setTimeout(()=>{if(activeId.value)fitView({padding:.18,duration:220})},120)}
function observeCanvas(){if(!flowCanvas.value)return;resizeObserver?.disconnect();resizeObserver=new ResizeObserver(scheduleFit);resizeObserver.observe(flowCanvas.value)}
function syncFullscreen(){isFullscreen.value=document.fullscreenElement===document.documentElement;void nextTick().then(scheduleFit)}
async function toggleFullscreen(){if(document.fullscreenElement){await document.exitFullscreen();return}if(isFullscreen.value){isFullscreen.value=false;void nextTick().then(scheduleFit);return}try{await document.documentElement.requestFullscreen()}catch{isFullscreen.value=true;void nextTick().then(scheduleFit)}}
onMounted(async()=>{document.addEventListener('fullscreenchange',syncFullscreen);await Promise.all([loadNodeTypes(),loadMindmapCategories()]);await loadSystems()})
onBeforeUnmount(()=>{document.removeEventListener('fullscreenchange',syncFullscreen);clearTimeout(fitTimer);resizeObserver?.disconnect()})
</script>
<template><section ref="pageRoot" class="page systems-page" :class="{fullscreen:isFullscreen}"><header class="page-head"><div><h1>脑图</h1><p>分类整理交易系统、复盘流程与学习笔记，支持手动版本保存与回撤</p></div><div class="page-actions"><n-button @click="openTemplates">脑图模板</n-button><n-button @click="openCategoryManager">管理分类</n-button><n-button type="primary" @click="openSystem()">新建脑图</n-button></div></header>
 <nav class="image-category-tabs mindmap-category-tabs panel" aria-label="脑图分类"><button :class="{active:categoryFilter===ALL}" :aria-pressed="categoryFilter===ALL" @click="selectCategory(ALL)"><span>全部</span><b>{{mindmapTotal}}</b></button><button v-for="item in visibleMindmapCategories" :key="item.id" :class="{active:categoryFilter===item.value}" :style="{'--category-color':item.color||'#3ec9c5'}" :aria-label="`查看${item.label}分类的全部脑图`" :aria-pressed="categoryFilter===item.value" @click="selectCategory(item.value)"><i/><span>{{item.label}}</span><b>{{item.mindmap_count}}</b></button><button class="category-add" aria-label="创建脑图分类" @click="openCategoryManager">＋ 新建分类</button></nav>
 <div class="systems-grid">
 <aside class="panel system-list-panel"><div class="panel-head system-list-head"><h3>我的脑图</h3><span>{{systems.length}} 张</span></div><div class="mindmap-filters"><n-input v-model:value="searchQuery" clearable size="small" placeholder="搜索名称或说明" @keyup.enter="loadSystems()" @clear="loadSystems()"/><n-select v-model:value="statusFilter" size="small" :options="[{label:'全部状态',value:ALL},{label:'草稿',value:'draft'},{label:'执行中',value:'active'},{label:'已归档',value:'archived'}]" @update:value="loadSystems()"/><n-button size="small" @click="loadSystems()">筛选</n-button></div><button v-for="system in systems" :key="system.id" class="system-choice" :class="{active:system.id===activeId}" :style="{'--system-color':system.color}" @click="select(system.id)"><i></i><span><strong>{{system.name}}</strong><small>{{system.category}} · {{system.node_count}} 节点</small></span><n-tag size="tiny" :type="system.status==='active'?'success':'default'">{{statusLabel[system.status]}}</n-tag></button><div v-if="!systems.length" class="empty-box"><strong>没有符合筛选条件的脑图</strong></div></aside>
 <div class="panel flow-workbench"><template v-if="activeSystem"><div class="flow-toolbar"><div><h2><i :style="{background:activeSystem.color}"></i>{{activeSystem.name}}<n-tag size="small">{{activeSystem.category}}</n-tag><n-tag size="small" :type="activeSystem.status==='active'?'success':'default'">{{statusLabel[activeSystem.status]}}</n-tag><n-tag size="small" :type="(detail?.quality.score||0)>=85?'success':(detail?.quality.score||0)>=65?'warning':'error'">完整度 {{detail?.quality.score||0}}</n-tag></h2><p>{{activeSystem.markets||'未限定品种'}} · {{activeSystem.timeframes||'未限定周期'}} · {{detail?.nodes.length||0}} 节点<span v-if="detail?.quality.missing.length"> · 待补：{{detail.quality.missing.join('、')}}</span></p></div><n-space class="flow-toolbar-actions"><n-button v-if="activeSystem.resource_url" size="small" tag="a" :href="activeSystem.resource_url" target="_blank">视频 / 资料 ↗</n-button><n-button size="small" type="primary" ghost @click="showShare=true">分享</n-button><n-button size="small" @click="openVersionHistory">版本 / 回撤</n-button><n-button size="small" @click="editCurrent">设置</n-button><n-dropdown trigger="click" :options="moreOptions" @select="handleMore"><n-button size="small">更多</n-button></n-dropdown><n-button size="small" @click="toggleFullscreen">{{isFullscreen?'退出全屏':'全屏'}}</n-button><n-button size="small" type="error" ghost @click="removeSystem">删除</n-button></n-space></div><div v-if="activeSystem.description" class="flow-description">{{activeSystem.description}}</div><div ref="flowCanvas" class="flow-canvas" @dblclick="editNodeAtPoint"><n-spin v-if="loading" class="flow-loading"/><VueFlow v-model:nodes="flowNodes" v-model:edges="flowEdges" :min-zoom=".18" :max-zoom="1.8" :nodes-draggable="false" :zoom-on-double-click="false" fit-view-on-init @node-double-click="editFlowNode"><Background pattern-color="#243042" :gap="22" :size="1"/><template #node-system="props"><SystemNodeCard :data="props.data"/></template></VueFlow><div class="flow-controls" @dblclick.stop><button title="放大" aria-label="放大脑图" @click="zoomIn({duration:180})">＋</button><button title="缩小" aria-label="缩小脑图" @click="zoomOut({duration:180})">−</button><button title="适应画布" aria-label="适应画布" @click="fitView({padding:.18,duration:220})">适应</button></div><span class="flow-touch-hint">双指缩放 · 单指拖动画布</span></div></template><div v-else class="empty-box"><strong>当前分类暂无脑图</strong><p>可以新建脑图，或切换上方分类</p></div></div>
 </div>
 <n-modal v-model:show="showSystemForm" preset="card" :title="editingSystemId?'编辑脑图':'新建脑图'" class="form-modal"><n-form label-placement="top"><n-grid :cols="2" :x-gap="12"><n-form-item-gi label="脑图名称"><n-input v-model:value="systemForm.name"/></n-form-item-gi><n-form-item-gi label="脑图分类"><n-select v-model:value="systemForm.category" :options="mindmapCategoryOptions" placeholder="先在设置中创建分类"/></n-form-item-gi></n-grid><n-form-item label="脑图说明"><n-input v-model:value="systemForm.description" type="textarea" :rows="4"/></n-form-item><n-form-item label="根级视频 / 网盘资料链接"><n-input v-model:value="systemForm.resource_url" placeholder="https://...（仅配置在整张脑图，不配置到子节点）"/></n-form-item><n-grid :cols="2" :x-gap="12"><n-form-item-gi label="适用品种"><n-input v-model:value="systemForm.markets" placeholder="XAUUSD, EURUSD"/></n-form-item-gi><n-form-item-gi label="适用周期"><n-input v-model:value="systemForm.timeframes" placeholder="15M, 1H"/></n-form-item-gi><n-form-item-gi label="状态"><n-select v-model:value="systemForm.status" :options="[{label:'草稿',value:'draft'},{label:'执行中',value:'active'},{label:'已归档',value:'archived'}]"/></n-form-item-gi><n-form-item-gi label="主题色"><n-color-picker v-model:value="systemForm.color" :show-alpha="false"/></n-form-item-gi></n-grid><n-checkbox v-if="!editingSystemId" v-model:checked="systemForm.template">创建市场、入场、风控、出场和复盘基础分支</n-checkbox><div class="modal-actions"><n-button @click="showSystemForm=false">取消</n-button><n-button type="primary" @click="saveSystem">保存</n-button></div></n-form></n-modal>
 <n-modal v-model:show="showCategories" preset="card" title="管理脑图分类" class="category-modal"><p class="category-help">分类会显示为脑图页面顶部的筛选按钮。拖动分类行可调整按钮顺序；使用中的分类不能停用或删除。</p><div class="category-editor panel"><n-input v-model:value="categoryForm.name" maxlength="60" show-count placeholder="分类名称，例如：交易认知" @keyup.enter="saveCategory"/><n-color-picker v-model:value="categoryForm.color" :show-alpha="false"/><n-button type="primary" :loading="categorySaving" @click="saveCategory">{{editingCategoryId?'保存改名':'创建分类'}}</n-button><n-button v-if="editingCategoryId" @click="cancelCategoryEdit">取消编辑</n-button></div><div v-if="mindmapCategories.length" class="category-manager-list"><div v-for="item in mindmapCategories" :key="item.id" draggable="true" :class="{editing:editingCategoryId===item.id}" @dragstart="dragCategoryId=item.id" @dragover.prevent @drop="dropCategory(item.id)"><span class="drag-handle" title="拖动排序">⋮⋮</span><i :style="{background:item.color||'#3ec9c5'}"/><div><strong>{{item.label}}</strong><small>{{item.mindmap_count}} 张脑图</small></div><n-switch :value="Boolean(item.is_active)" :disabled="Boolean(item.is_active)&&Number(item.mindmap_count)>0" size="small" @update:value="toggleCategory(item,$event)"/><n-button size="tiny" @click="editCategory(item)">改名</n-button><n-button size="tiny" type="error" ghost :disabled="Number(item.mindmap_count)>0" @click="removeCategory(item)">删除</n-button></div></div><div v-else class="empty-box compact"><strong>还没有分类</strong><p>在上方输入名称即可创建</p></div></n-modal>
 <n-modal v-model:show="showVersions" preset="card" title="脑图版本与整图回撤" class="history-modal"><div class="version-head"><p>最多保留最近 30 个手动版本；回撤前会自动保存当前内容。</p><n-button size="small" type="primary" @click="saveVersion">保存当前版本</n-button></div><div v-if="versions.length" class="version-list"><article v-for="item in versions" :key="item.id"><div><strong>{{item.label||item.action}}</strong><small>{{new Date(item.created_at).toLocaleString()}} · {{Math.ceil(item.snapshot_size/1024)}} KB</small></div><n-space><n-button size="small" @click="restoreVersion(item)">回撤到此版本</n-button><n-button size="small" type="error" ghost @click="removeVersion(item)">删除</n-button></n-space></article></div><div v-else class="empty-box compact"><strong>还没有历史版本</strong><p>点击“保存当前版本”即可创建。</p></div></n-modal>
 <n-modal v-model:show="showTemplates" preset="card" title="脑图模板" class="history-modal"><p class="category-help">模板保存整张脑图结构；使用模板会创建独立副本，不影响模板本身。</p><div v-if="templates.length" class="version-list"><article v-for="item in templates" :key="item.id"><div><strong>{{item.name}}</strong><small>{{item.category}} · {{item.node_count}} 节点</small></div><n-space><n-button size="small" type="primary" @click="useTemplate(item)">使用模板</n-button><n-button size="small" type="error" ghost @click="deleteTemplate(item)">删除</n-button></n-space></article></div><div v-else class="empty-box compact"><strong>还没有脑图模板</strong><p>在任意脑图的“更多”菜单中保存为模板。</p></div></n-modal>
 <ShareDialog v-if="activeSystem" v-model:show="showShare" target-type="mindmap" :target-id="activeSystem.id" :target-title="activeSystem.name"/>
 <n-modal v-model:show="showNodeForm" preset="card" :title="editingNodeId?'编辑节点':'添加节点'" class="form-modal"><n-form label-placement="top"><n-grid :cols="2" :x-gap="12"><n-form-item-gi label="节点名称"><n-input v-model:value="nodeForm.title"/></n-form-item-gi><n-form-item-gi label="节点类型"><n-select v-model:value="nodeForm.node_type" :options="nodeTypes" :disabled="nodeForm.node_type==='root'"/></n-form-item-gi></n-grid><n-form-item v-if="nodeForm.node_type!=='root'" label="父节点"><n-select v-model:value="nodeForm.parent_id" :options="parentOptions"/></n-form-item><n-form-item label="节点说明"><n-input v-model:value="nodeForm.content" type="textarea" :rows="4"/></n-form-item><n-form-item v-if="nodeForm.node_type!=='root'" label="引用规则"><n-select v-model:value="nodeForm.rule_id" clearable filterable :options="ruleOptions" placeholder="不引用规则"/></n-form-item><n-grid :cols="2" :x-gap="12"><n-form-item-gi label="同级排序"><n-input-number v-model:value="nodeForm.sort_order"/></n-form-item-gi><n-form-item-gi label="默认折叠"><n-switch v-model:value="nodeForm.is_collapsed"/></n-form-item-gi></n-grid><div class="modal-actions"><n-button :disabled="nodeSaving" @click="showNodeForm=false">取消</n-button><n-button type="primary" :loading="nodeSaving" @click="saveNode">保存</n-button></div></n-form></n-modal>
</section></template>
